"""panel_v3.py = lora_tactile/tactile_panel.py drawing RELATIVE touch (user 2026-10-22: touch must be relative, not absolute
newtons; absolute grip force depends on mass, friction and each person's margin, none of which RGB shows). Same layout,
PAD_LO and sqrt encoding; the panel shows F / S, S = the episode's touch scale (ge_scale.py: median total force over its
contact frames, whole episode), so F_MAX / BAR_MAX here are in units of S. Caps from the measured relative distribution of
the dual-mode dataset (dataset/scale.json, built under panel v2): the 99.5th percentiles of contact readings and of the per-
frame largest finger total, rounded up -> < 0.5 % of contact readings and < 0.5 % of frames clip. The model never sees S.
  THR_REL  relative contact threshold for scoring (= 0.15 N at the median real S), applied to prediction and truth alike
  TOT_REL  relative "in contact" threshold on the total (onset / release / contact time; 5 N at the median real S)
  python make_panel_v3.py   (in lora_ge/; reads ../lora_tactile/tactile_panel.py and the dataset's scale.json)"""
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent; t = (Path("/scratch/project/prj-02-phai-lab/nuo/agentic-r2s2r/experiments/R2S2V_mug") / "lora_tactile/tactile_panel.py").read_text()
sc = json.loads(Path("/scratch/project/prj-02-phai-lab/nuo/agentic-r2s2r/outputs/R2S2V_mug/lora_ge/dataset/scale.json").read_text())
old = "F_MAX, PAD_LO, BAR_MAX = 3.0, 24, 30.0"; assert t.count(old) == 1
med = sc["S_real"]["median"]
t = t.replace(old, f'F_MAX, PAD_LO, BAR_MAX = {sc["taxel_cap_rel"]}, 24, {sc["bar_cap_rel"]}     # relative units (x S)\n'
                   f'PANEL_VERSION = "v3"; RELATIVE = True\nTHR_REL, TOT_REL = {round(0.15 / med, 4)}, {round(5.0 / med, 3)}   # 0.15 N / 5 N at the median real S ({med:.1f} N)', 1)
t = ('"""GENERATED by lora_ge/make_panel_v3.py from lora_tactile/tactile_panel.py: panel v3, RELATIVE touch (F / S); caps '
     f'{sc["taxel_cap_rel"]} S per taxel, {sc["bar_cap_rel"]} S per finger bar (clip {100 * sc["clip_taxel"]:.2f} % of contact readings, '
     f'{100 * sc["clip_frames"]:.2f} % of frames). Do not edit."""\n') + t
(HERE / "panel_v3.py").write_text(t); print("wrote panel_v3.py", sc["taxel_cap_rel"], sc["bar_cap_rel"], round(0.15 / med, 4), round(5.0 / med, 3))
